import unittest

from units import to_meters


class ToMeters(unittest.TestCase):
    def test_km(self):
        self.assertEqual(to_meters(2, "km"), 2000)

    def test_mm(self):
        self.assertAlmostEqual(to_meters(5, "mm"), 0.005)

    def test_unknown(self):
